INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65867308', 65867308, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Vaksin IPV untuk Jemaah Haji Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 9096727000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Vaksin Polio untuk Jemaah Haji Tahun 2026 sebanyak 41.560 vial dengan estimasi harga satuan Rp218.882', 'Spesifikasi Vaksin IPV untuk Jemaah Haji sebagai berikut : 1. Nama : Inactivated Polio Vaccine. 2. Komposisi Vaksin : Setiap satu dosis (0,5 ml) mengandung: Virus Poliomyelitis tipe 1: Mahoney 40 UD (unit antigen D), Virus Poliomyelitis tipe 2: MEF-1 8 UD, Virus Poliomyelitis tipe 3: Saukett 32 UD, 3. Indikasi Vaksin : Mencegah penyakit Polio tipe 1, tipe 2, dan tipe 3. 4. Kemasan : Dikemas dalam multi dose. Dalam setiap kemasan ampul/vial/pouch dilengkapi dengan indikator Vaccine Vial Monitor (VVM). Dilengkapi dengan nomor batch, masa kedaluwarsa, serta brosur/leaflet yang berisi petunjuk pemakaian, indikasi, kontraindikasi, dan petunjuk penggunaan VVM dalam Bahasa Indonesia. 5. Masa Kadaluwarsa : Masa kedaluwarsa vaksin saat diterima di pusat/provinsi minimal 14 bulan. 6. Izin Vaksin : Telah teregistrasi oleh Badan Pengawas Obat dan Makanan (BPOM). 7. Persyaratan Rilis dan Pendistribusian Vaksin : Vaksin telah mendapatkan persetujuan lot release dalam bentuk sertifikat Certificate of Release (CoR) dari BPOM sebelum didistribusikan. Dilengkapi dengan Vaccine Arrival Report (VAR) dan alat pemantau suhu secara kontinu (data logger).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2401342);
