INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65867940', 65867940, 'analyze_legacy', 'Kota Cirebon', 'kabkota', 'DINAS KESEHATAN', 'Belanja Makanan dan Minuman Aktivitas Lapangan (Prolanis) PKM Cangkol', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Cirebon (Kota)', 4900000, 'January 2026', 'BLUD', 1, 1, '1 tahun', 'Kegiatan Belanja Makanan dan Minuman dalam Aktivitas Prolanis merupakan bentuk dukungan logistik yang bertujuan menyediakan konsumsi sehat bagi peserta senam bersama. Makanan dan minuman yang disiapkan dipilih secara selektif sesuai prinsip gizi seimbang, rendah gula, rendah garam, dan rendah lemak, guna mendukung pengelolaan penyakit kronis seperti hipertensi dan diabetes. Penyediaan ini dilakukan sebelum atau sesudah sesi senam, sebagai bagian dari pelayanan menyeluruh yang memperhatikan kebutuhan nutrisi peserta. Selain memenuhi kebutuhan konsumsi, kegiatan ini juga menjadi sarana edukasi dan pembiasaan pola makan sehat dalam kehidupan sehari-hari. Peserta diajak mengenali pilihan makanan yang tepat, baik dari segi komposisi maupun porsi, sehingga dapat diterapkan di rumah secara mandiri. Dengan adanya penyediaan makanan dan minuman yang sehat dan terkontrol, diharapkan peserta Prolanis semakin termotivasi untuk menjaga gaya hidup sehat secara konsisten dan berkelanjutan.', 'No Barang/Jasa Spesifikasi 1 Snack Prinsip gizi seimbang, rendah gula, rendah garam, dan rendah lemak', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2402856);
